import {helpMethod} from './question-help.mjs?v=3.9';
export const external = (url,label) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${label}<span class="external-mark" aria-hidden="true"> ↗</span></a>`;
export const experimental = (compact=false) => `<aside class="notice ${compact?'compact':''}"><span class="notice-symbol" aria-hidden="true">i</span><div><strong>Český pracovní překlad · dosud nevalidovaný</strong>${compact?'':`<p>Vychází z původního IPIP-50. Toto české znění nemá vlastní psychometrické ověření a není adaptací Hřebíčkové a spoluautorů. <a href="#podklady">Co to znamená pro výsledek →</a></p>`}</div></aside>`;

export function sciencePage() {
  return `<div class="page-head wrap"><span class="eyebrow">ZDROJE & METODIKA</span><h1>Na čem to <em>stojí.</em></h1><p class="lead">Od původních otázek až k číslu ve tvém profilu. Tady najdeš původ, výpočet i hranice toho, co z výsledku můžeme vyčíst.</p></div>
  <div class="wrap reading-layout"><aside class="contents"><span class="eyebrow">V TÉTO SEKCI</span><a href="#podklady" data-jump="evidence">Co je ověřené</a><a href="#podklady" data-jump="calculation">Jak počítáme</a><a href="#podklady" data-jump="research">Výzkumný základ</a><a href="#podklady" data-jump="license">Překlad a licence</a><a href="#podklady" data-jump="limits">Omezení</a></aside><article class="reading">
  ${experimental()}
  <section id="evidence"><span class="section-number">01 / STAV OVĚŘENÍ</span><h2>Metoda má historii.<br>Každý překlad potřebuje své ověření.</h2><p>Využíváme <strong>50-item IPIP Big-Five Factor Markers</strong>: 50 položek, pět škál po deseti položkách. Zachováváme pořadí i skórovací klíč oficiálního vzoru. České otázky jsou vlastním pracovním překladem anglických položek. České popisy odpovědí, instrukce a výklad výsledků jsou také součástí této webové verze.</p>
  <div class="evidence-stack"><div><span class="status-dot green"></span><div><strong>Původní metoda</strong><p>Výzkumně používané položky IPIP a veřejný skórovací klíč. ${external('https://www.ipip.ori.org/New_IPIP-50-item-scale.htm','Původní dotazník')}</p></div></div><div><span class="status-dot amber"></span><div><strong>Tento český překlad</strong><p>Dosud bez psychometrické validace, českých norem a odborného posouzení psychologem. Vhodný jako orientační podnět k sebereflexi.</p></div></div><div><span class="status-dot muted"></span><div><strong>Výsledkové texty</strong><p>Vlastní popisy webu podle směru skóre. Nejsou součástí validovaného manuálu a neposkytují diagnózu.</p></div></div></div></section>
  <section id="calculation"><span class="section-number">02 / OTEVŘENÝ VÝPOČET</span><h2>Z odpovědí k pěti škálám.</h2><p>Odpověď má hodnotu 1 až 5. U přímo skórovaných položek ji ponecháme. U obrácených použijeme <strong>6 − odpověď</strong>: z 1 se stane 5, z 2 bude 4 a 3 zůstává 3. Součtem deseti hodnot vznikne skóre 10–50. Pro čitelnost ukazujeme také průměr 1–5, tedy součet dělený deseti. ${external('https://www.ipip.ori.org/newScoringInstructions.htm','Oficiální pravidla skórování')}</p>
  <div class="formula"><span>10 odpovědí</span><b>→</b><span>otočení podle klíče</span><b>→</b><span>součet ÷ 10</span></div>
  <div class="table-scroll"><table><caption>Položky podle oficiálního pořadí IPIP-50</caption><thead><tr><th>Škála</th><th>Přímo skórované</th><th>Obrácené</th></tr></thead><tbody>
  <tr><th>Extraverze</th><td>1, 11, 21, 31, 41</td><td>6, 16, 26, 36, 46</td></tr><tr><th>Přívětivost</th><td>7, 17, 27, 37, 42, 47</td><td>2, 12, 22, 32</td></tr><tr><th>Svědomitost</th><td>3, 13, 23, 33, 43, 48</td><td>8, 18, 28, 38</td></tr><tr><th>Emoční stabilita</th><td>9, 19</td><td>4, 14, 24, 29, 34, 39, 44, 49</td></tr><tr><th>Intelekt a představivost</th><td>5, 15, 25, 35, 40, 45, 50</td><td>10, 20, 30</td></tr></tbody></table></div>
  <p>${external('https://www.ipip.ori.org/newBigFive5broadKey.htm','Porovnat s původním klíčem')} · Používáme vždy 10položkovou škálu uvedenou u každého faktoru, nikoli delší 20položkové varianty na stejné stránce.</p>
  <details><summary>Jak vzniká slovní shrnutí a graf?</summary><p>Graf ukazuje průměr na stupnici 1–5. Pro slovní popis web používá tři orientační oblasti: 1–2,5, více než 2,5 a méně než 3,5, a 3,5–5. Hranice jsou <strong>vlastní zobrazovací konvence</strong>, nikoli výzkumné normy, klinické prahy nebo rozdělení lidí na typy. Střed grafu je střed odpovědní škály, nikoli průměr české populace.</p><p>Neuvádíme percentily ani celkové skóre „kvality osobnosti“. Ze škál nevytváříme pořadí silných a slabých stránek; stejná hodnota v různých škálách nemá význam stejného populačního postavení.</p></details>
  <details><summary>Co se stane při vynechané odpovědi?</summary><p>Otázku můžeš přeskočit i později vymazat. Skóre vypočítáme pouze pro škálu s deseti platnými odpověďmi. Chybějící hodnoty nenahrazujeme nulou, středem ani průměrem. U nedokončené škály ukážeme počet odpovědí a možnost doplnění. Jde o konzervativní pravidlo této implementace.</p></details>
  <details><summary>Proč jsou některé otázky opačně?</summary><p>Jedny výroky popisují určitý rys přímo, jiné opačným směrem. Například souhlas s tím, že se držíš v pozadí, přispívá k nižší extraverzi. Reverzní skórování proto není penalizace ani známka špatné odpovědi.</p></details></section>
  <section id="research"><span class="section-number">03 / VÝZKUM A PŮVOD</span><h2>Zdroje, které si můžeš otevřít.</h2>
  <div class="source-card"><span class="source-tag">PŘÍMÝ PODKLAD TÉTO VERZE</span><h3>IPIP: položky, administrace a skórovací klíč</h3><p>International Personality Item Pool. Původní anglické položky, pořadí 50položkového vzoru a přiřazení k pěti škálám tvoří základ této implementace. Anglický originál je dostupný i u každé otázky.</p><div class="source-links">${external('https://www.ipip.ori.org/New_IPIP-50-item-scale.htm','Položky a administrace')}${external('https://www.ipip.ori.org/newBigFive5broadKey.htm','Klíč')}${external('https://www.ipip.ori.org/newScoringInstructions.htm','Výpočet')}</div></div>
  <div class="source-card"><span class="source-tag">ZÁKLAD FAKTOROVÝCH MARKERŮ</span><h3>Goldberg, L. R. (1992)</h3><p><cite>The development of markers for the Big-Five factor structure.</cite> Psychological Assessment, 4, 26–42.</p><p>Oficiální IPIP uvádí tuto práci jako podklad markerů, k nimž se jeho škály vztahují. Nejde o validaci tohoto českého překladu ani o návod k diagnostice.</p>${external('https://www.ipip.ori.org/New_IPIP-50-item-scale.htm','Citace a souvislost na webu IPIP')}</div>
  <div class="source-card"><span class="source-tag">SOUVISEJÍCÍ ČESKÝ VÝZKUM · JINÉ ZNĚNÍ</span><h3>Hřebíčková, Jelínek, Květon & Benkovič (2023)</h3><p><cite>Psychometric properties of the Czech adaption of the IPIP-BFM-50 and the Mini-IPIP-BFM-20.</cite> Československá psychologie, 67(2), 101–120. DOI: 10.51561/cspsych.67.2.101.</p><p>Studie zkoumala 715 lidí ve věku 15–26 let. Podporuje použití autorské české adaptace v daném kontextu; věkové normy nestanovila. <strong>Její české položky zde nepoužíváme a její koeficienty spolehlivosti nepřipisujeme tomuto webu.</strong></p><div class="source-links">${external('https://ceskoslovenskapsychologie.cz/index.php/csps/article/view/243','Článek a abstrakt')}${external('https://ceskoslovenskapsychologie.cz/index.php/csps/article/download/243/128','Plný text PDF')}</div></div>
  <div class="source-card"><span class="source-tag">INTERPRETACE A SROVNÁNÍ</span><h3>IPIP: interpretace výsledků a normy</h3><p>Pro srovnání s ostatními je potřeba vhodný referenční soubor. Tento web žádný český normovací soubor pro svůj překlad nepoužívá.</p><div class="source-links">${external('https://www.ipip.ori.org/newNorms.htm','Normy a datové soubory')}${external('https://www.ipip.ori.org/InterpretingIndividualIPIPScaleScores.htm','Interpretace IPIP')}</div></div></section>
  <section id="license"><span class="section-number">04 / PŘEKLAD A PODMÍNKY POUŽITÍ</span><h2>Odkud pochází české znění?</h2><p>Původní položky a škály IPIP jsou public domain. IPIP výslovně umožňuje jejich použití a překlady. České věty na tomto webu byly vytvořeny samostatně z anglického originálu pro tuto verzi projektu Osobnosti s pomocí AI; neprošly validací ani odbornou revizí psychologem. ${external('https://www.ipip.ori.org/newPermission.htm','Podmínky IPIP')}</p><p>Publikovaná česká adaptace z roku 2023 uvádí u překladu specifické omezení na nekomerční vědecké použití a požaduje svolení pro jiné využití (strana 101). Proto ji tento web nereprodukuje. Obecná licence článku a podmínky konkrétního překladu nejsou zde považovány za zaměnitelné.</p><p><strong>Verze nástroje:</strong> ipip50-cs-working-1.0.0 · 27. 10. 2026. Zachováno: 50 položek, jejich pořadí, pětibodová stupnice a skórovací klíč. Vlastní: české znění, české instrukce a interpretační texty. Případná změna položek musí vytvořit novou verzi.</p></section>
  ${helpMethod('personality')}<section><h2>Co znamenají odpovědi u záporných vět</h2><p>Čísla 1 až 5 vyjadřují, nakolik tě vystihuje celý výrok. Tlačítka proto zobrazují úplné názvy odpovědí. U vět se záporem nebo snadno zaměnitelným směrem navíc ukazujeme vlastní slovní vysvětlení obou konců stupnice. Například u „Abstraktní myšlenky mě nezajímají“ odpovídá 1 zájmu a 5 nezájmu. Význam čísla tedy vždy závisí na konkrétní větě.</p><p>Tyto popisy jsou orientační pomůcka vytvořená s pomocí AI, nikoli další položky nebo nové skórování. Jejich vliv na odpovědi zatím není odborně ověřený. Dříve uložené odpovědi nepřepisujeme; pokud jsi některou větu pochopil/a obráceně, můžeš svou odpověď upravit.</p></section><section id="limits"><span class="section-number">05 / HRANICE VÝSLEDKU</span><h2>Co dotazník neumí.</h2><p>Výsledek vychází z toho, jak se právě popisuješ. Ovlivňuje ho porozumění otázkám, aktuální situace i ochota odpovídat otevřeně. Bez ověření tohoto překladu neznáme přesnost jeho měření ani to, zda funguje srovnatelně u různých skupin lidí.</p><ul class="prose-list"><li>Není to psychologická diagnóza, IQ test ani výběrový nástroj pro zaměstnání.</li><li>Není to detektor lží nebo předpověď věrnosti, charakteru či osudu vztahu.</li><li>Koeficient reliability není procento přesnosti konkrétního výsledku. Tady žádný takový koeficient pro vlastní překlad netvrdíme.</li><li>Technická kontrola výpočtu není psychometrická validace.</li></ul><p>Pro odborné posouzení je potřeba odpovídající metoda a kvalifikovaný odborník. Pro vlastní reflexi mohou být užitečné zejména konkrétní odpovědi a situace, které ti při nich přišly na mysl.</p></section>
  <div class="bottom-callout"><h3>Teď víš, co od výsledku čekat.</h3><a class="button" href="#uvod">Přejít k dotazníku <span aria-hidden="true">↗</span></a></div>
  </article></div>`;
}

export function privacyPage(){return `<div class="wrap narrow page-head"><span class="eyebrow">SOUKROMÍ A ULOŽENÍ</span><h1>Tvoje data.<br><em>Tvoje rozhodnutí.</em></h1><p class="lead">Testy lze vyplnit bez účtu. Uložení na server, zpřístupnění dalším lidem a AI vysvětlení jsou samostatné, dobrovolné volby.</p></div><article class="wrap narrow reading"><section><h2>Jen pro tuto relaci</h2><p>Výpočty běží v prohlížeči. Ve výchozím stavu ukládáme rozpracované odpovědi a postup pouze do sessionStorage této karty. Obnovení stránky je zachová; normálním ukončením relace se odstraní. Některé prohlížeče je mohou vrátit při obnovení zavřených karet. Pro jisté odstranění použij smazání místního profilu. Pokud je úložiště zablokované, odpovědi zůstanou jen v paměti otevřené stránky a web na to upozorní. Nepoužíváme analytiku, reklamní cookies ani externí AI služby.</p></section><section><h2>Zapamatování bez účtu</h2><p>Po dokončení osobnostního i intimního testu nabízíme tři možnosti: účet, toto zařízení, nebo jen relaci. Volba zařízení ukládá do localStorage jen vybraný test, jeho postup, datum vyhodnocení a verze dotazníků. U každého testu rozhoduješ samostatně. Horní volba „Pamatovat si oba testy v tomto prohlížeči“ výslovně zapne dlouhodobé ukládání obou modulů včetně intimních odpovědí. Při volbě relace či účtu pro konkrétní test se jeho dosavadní dlouhodobá místní kopie odstraní, ostatní test si ponechá vlastní nastavení. Výsledky se z odpovědí znovu spočítají. Místní uložení samo nic neposílá na server a neukládá přihlašovací klíče, porovnávací kódy ani partnerův profil.</p><p>Místní kopie nemá vlastní heslo ani šifrování aplikací. Každý s přístupem k tomuto profilu prohlížeče ji může otevřít. Na společném zařízení nech zapamatování vypnuté. Je vázané na stejný prohlížeč a adresu webu; nepřenáší se automaticky na jiný telefon. Není to záloha: vymazání dat webu, soukromé okno nebo zásah prohlížeče může data odstranit.</p><p>Odškrtnutí volby smaže uloženou místní kopii; v této kartě můžeš dál pracovat. Smazání celého místního profilu odstraní i aktuální odpovědi a zapamatování vypne. Částečné smazání osobnosti nebo intimity odstraní vybranou část i z místní kopie. Ve druhé otevřené kartě po smazání kopie odpovědi také vyčistíme; při jiných souběžných změnách ukládání pozastavíme, aby se starší odpovědi nevrátily.</p><button class="button secondary" data-action="reset" data-scope="all">Smazat celý místní profil</button></section><section><h2>Dobrovolný účet a ukládání</h2><p>Účet používá unikátní nickname a heslo, bez e-mailu a bez požadavku na skutečné jméno. Nickname nerozlišuje velikost písmen. Heslo má 15–128 znaků a ukládá se jako Argon2id hash se samostatnou solí, nikoli v čitelné podobě. Zapomenuté heslo nelze obnovit; při přihlášení ho můžeš změnit s ověřením současného hesla. Starší účty se mohou přihlásit původním ID a klíčem a nastavit nové přihlášení bez ztráty výsledků. Převod původní klíč zneplatní. Přihlášení používá nezbytnou cookie HttpOnly, Secure a SameSite Strict a trvá nejvýše 12 hodin. Volitelně lze zůstat přihlášený/á na tomto zařízení až 30 dní díky další cookie s náhodným tokenem; v databázi je pouze hash jeho tajné části. Změna hesla nebo převod zneplatní ostatní přihlášení. Tyto cookies neobsahují odpovědi ani heslo.</p><p>Výsledky uložené na serveru jsou kdykoliv dostupné z účtu, i na jiném zařízení, dokud je nesmažeš a máš přihlašovací údaje. Můžeš z nich vytvořit kód pro párové porovnávání. Samotné porovnání vlastních odpovědí s partnerovým kódem je možné i bez účtu. Při přístupu přes HTTPS můžeš výslovně uložit osobnost, intimní část nebo obojí. Po volbě účtu na konci testu přihlášení automaticky dokončí uložení právě vybraného testu. Uložený snímek obsahuje vybrané jednotlivé odpovědi, verze a čas uložení. Intimní uložení není předem zaškrtnuté. Účet má nejvýše 20 výsledků; změny v dotazníku je samy nepřepisují.</p><p>Data jsou na tomto serveru v samostatné databázi mimo veřejný adresář, šifrovaná serverovým klíčem. Správce serveru má technickou možnost data přečíst. Nejde o koncové šifrování, při kterém by je správce nemohl zpřístupnit.</p></section><section><h2>Kódy pro porovnání</h2><p>Samotné ID účtu ani výsledku cizí data neotevře. Porovnávací kód obsahuje ID výsledku a náhodnou tajnou část. Každý, kdo zná celý kód, může po dobu 7 dní načíst zvolené kategorie. Proto ho posílej jen člověku, kterému chceš tento výběr ukázat. Kód lze kdykoli zrušit.</p><p>Osobnost a role zpřístupňují číselné průměry, nikoli znění jednotlivých odpovědí. Kontext a aktivity zpřístupňují jejich označené volby. „Nechci uvést“ se neposílá; nevyplněné a neúplné hodnoty neodhadujeme. Před vytvořením kódu vidíš náhled. Intimní kategorie jsou předem vypnuté. Porovnání se zpracuje v prohlížeči a jako nový výsledek se automaticky neukládá.</p></section><section><h2>Dobrovolné AI vysvětlení</h2><p>V porovnání lze vybrat kategorie pro vysvětlení místním modelem. Intimní kategorie jsou výchozí vypnuté. Až kliknutím na „Vytvořit rozbor“ odešleš zvolené průměry či odpovědi obou profilů na server tohoto webu. Předem si můžeš prohlédnout podklady. Model nedostává porovnávací kódy, ID účtů ani přihlášení. Nevybrané a soukromé odpovědi se pro AI neposílají.</p><p>Model běží na stejném aplikačním serveru; neposíláme dotaz externímu poskytovateli AI. Hranice a neurčené preference vysvětlují pevná pravidla mimo model. Aplikace AI vstupy ani výstupy neukládá do účtu či místního úložiště a nezapisuje obsah požadavků do vlastních logů. Správce serveru má technickou možnost sledovat zpracování. Vysvětlení zůstává v otevřené stránce do změny výběru, vymazání porovnání nebo obnovení stránky.</p><p>Použij údaje obou lidí jen s jejich svolením k tomuto způsobu zpracování. AI vybírá z připravených otázek; nepíše vlastní tvrzení o profilech. Výklad podle pravidel ani výběr otázek nepředstavují odborné posouzení.</p></section><section><h2>Osobní AI rozbor výsledku</h2><p>V Mém profilu můžeš samostatně vytvořit osobní rozbor. Na tvůj pokyn dostane místní model vybrané číselné výsledky a jejich popisy; intimní oblasti jsou výchozí vypnuté. Aktivity, hranice a neurčené odpovědi vysvětluje prohlížeč podle pravidel a modelu se neposílají. Model nepřebírá přihlášení, kódy ani původní položkové odpovědi osobnostního testu.</p><p>Zde model píše vlastní souvislý výklad. Může se mýlit i při správném formátu. Rozbor a zpětná vazba „sedí / někdy / nesedí“ zůstávají pouze v otevřené kartě, bez automatického uložení do účtu, místního úložiště nebo aplikačních logů. Změna odpovědí či kategorií, smazání, odhlášení nebo obnovení stránky je vymaže. <a href="#podklady-rozbor">Podklady a omezení osobního rozboru →</a></p></section><section><h2>Co smaže které tlačítko</h2><ul><li><strong>Smazání v Mém profilu:</strong> vybrané odpovědi v tomto panelu i jejich místní kopii v prohlížeči. Uložené snímky na serveru zůstanou.</li><li><strong>Smazat uložený výsledek v Účtu:</strong> jeho snímek a všechny jeho kódy. Aktuální neuložené odpovědi zůstanou.</li><li><strong>Zrušit kód:</strong> zablokuje další načtení přes tento kód. Samotný výsledek zůstane soukromě v účtu.</li><li><strong>Smazat účet:</strong> účet, všechny jeho výsledky a kódy. Zneplatní přihlášení a vyčistí aktuální panel i místní kopii v prohlížeči.</li><li><strong>Odhlášení:</strong> ukončí přihlášení, odstraní aktuální odpovědi, jejich místní kopii i porovnání z panelu. Uložené výsledky zůstanou.</li></ul><p>Data držíme do smazání uživatelem; kódy po 7 dnech přestanou fungovat. Web nevytváří vlastní zálohy výsledků. Případné systémové zálohy serveru má pod kontrolou jeho správce. Nemůžeme vzdáleně smazat dříve načtené stránky, screenshoty nebo stažené soubory u tebe či druhého člověka.</p><a class="button secondary" href="#ucet">Spravovat účet a uložená data →</a></section><section><h2>Obrázky, exporty a přístupové záznamy</h2><p>PNG a další exporty vznikají v prohlížeči. Intimní karty přidáš výslovnou volbou a před stažením vidíš náhled. Web žádné obrázky ani zprávy lidem automaticky neposílá.</p><p>Webserver a HTTPS brána mohou zaznamenávat IP adresu, čas a navštívenou cestu. Soukromé klíče, kódy ani odpovědi nedáváme do URL; API je přijímá v těle požadavku a do aplikačních logů jejich obsah nepíše. Pro omezení zneužití uchováváme krátkodobá počítadla požadavků, bez odpovědí. Nezaručujeme anonymitu vůči správci infrastruktury.</p><p>Odkazy na studie vedou k jejich provozovatelům. Nepřipojujeme k nim tvoje odpovědi.</p></section></article>`;}

export function readingPage(){return `<div class="wrap narrow page-head"><span class="eyebrow">PRŮVODCE VÝSLEDKEM</span><h1>Čti čísla<br><em>v souvislostech.</em></h1><p class="lead">Pět pohledů na tvé odpovědi. Každý zachycuje jinou část toho, jak se popisuješ.</p></div><article class="wrap narrow reading">${experimental()}<section><h2>3,8 z 5 není 76. percentil</h2><p>Číslo je průměr deseti odpovědí po otočení příslušných položek. Ukazuje místo na stupnici dotazníku, nikoli pořadí mezi ostatními lidmi. Střed 3 není populační průměr.</p></section><section><h2>Průměr může skrýt rozdíly</h2><p>Stejného průměru mohou dosáhnout různé kombinace odpovědí. V detailu škály si proto můžeš prohlédnout své odpovědi i výpočet. Ptej se, ve kterých situacích jednotlivé výroky platí.</p></section><section><h2>Vyšší nemusí znamenat lepší</h2><p>Výsledek nehodnotí tvoji hodnotu. Větší společenskost není totéž co kvalitnější vztahy a vyšší svědomitost není automaticky lepší pracovní výkon. U každé škály najdeš, co měří a co už z ní nevyplývá.</p></section><section><h2>Popisy jsou orientační</h2><p>Výklad se přepíná podle tří popisných oblastí stupnice. Jejich hranice 2,5 a 3,5 jsme zvolili pro čitelnost webu, nejsou to diagnostické prahy ani normy. Drobné změně přes hranici proto nepřisuzuj zvláštní význam.</p></section><section><h2>Z výsledku udělej otázku</h2><p>Zkus si vybavit dvě situace, ve kterých na tebe popis sedí, a jednu, ve které ne. Takové rozdíly mohou být pro sebeporozumění přínosnější než samotné číslo.</p><a class="text-link" href="#podklady">Celá metodika a zdroje →</a></section></article>`;}
